import { Component, ComponentInterface, Element, h, Host, Prop } from '@stencil/core';
import { fromEvent, Observable, Subject, takeUntil } from 'rxjs';

/**
 * @nativeEvent click - dispatched when the menu item is clicked
 * @slot default - default slot for the text content of the menu item
 * @slot description - named slot 'description', for any additional text below the main text
 * @slot start - named slot 'start', for any content on the left side of the menu item
 * @slot end - named slot 'end', for any content on the right side of the menu item
 */
@Component({
  tag: 'groupui-menu-item',
  styleUrl: 'menu-item.scss',
  shadow: { delegatesFocus: true },
})
export class MenuItem implements ComponentInterface {
  /**
   * If true, the menu item is disabled
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * If true, the menu item is active
   */
  @Prop({ reflect: true }) readonly active: boolean = false;

  /**
   * If true, the menu item is rendered with a divider line under it
   */
  @Prop({ reflect: true }) readonly divider: boolean = false;

  /**
   * If true, the menu item functions as a checkbox item.
   * Do not use in combination with the `start` slot.
   */
  @Prop({ reflect: true }) readonly checkbox: boolean = false;

  /**
   * ARIA label for the start slot.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-start-slot' }) readonly a11yLabelStartSlot: string;

  /**
   * ARIA label for the end slot.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-end-slot' }) readonly a11yLabelEndSlot: string;

  @Element() host: HTMLElement;

  private itemMouseEnter = new Observable<Event>();
  private itemMouseDown = new Observable<Event>();
  private itemMouseUp = new Observable<Event>();
  private itemMouseLeave = new Observable<Event>();
  private destroy = new Subject<void>();

  componentDidLoad() {
    this.itemMouseEnter = fromEvent(this.host, 'mouseenter').pipe(takeUntil(this.destroy));
    this.itemMouseLeave = fromEvent(this.host, 'mouseleave').pipe(takeUntil(this.destroy));
    this.itemMouseDown = fromEvent(this.host, 'mousedown').pipe(takeUntil(this.destroy));
    this.itemMouseUp = fromEvent(this.host, 'mouseup').pipe(takeUntil(this.destroy));
    this.subscribeToItemMouseEnter();
    this.subscribeToItemMouseLeave();
    this.subscribeToItemMouseDown();
    this.subscribeToItemMouseUp();
    this.setStartSlotAriaLabel();
    this.setEndSlotAriaLabel();
  }

  private setStartSlotAriaLabel() {
    const startSlot = this.startSlot();
    if (startSlot && this.a11yLabelStartSlot) {
      startSlot.setAttribute('aria-label', this.a11yLabelStartSlot);
    }
  }

  private setEndSlotAriaLabel() {
    const endSlot = this.endSlot();
    if (endSlot && this.a11yLabelEndSlot) {
      endSlot.setAttribute('aria-label', this.a11yLabelEndSlot);
    }
  }

  private startSlot(): HTMLElement {
    return this.host.querySelector('[slot="start"]') as HTMLElement;
  }

  private endSlot(): HTMLElement {
    return this.host.querySelector('[slot="end"]') as HTMLElement;
  }

  private subscribeToItemMouseEnter() {
    this.itemMouseEnter.subscribe(() => {
      this.addClassToCheckbox('hover');
    });
  }

  private subscribeToItemMouseLeave() {
    this.itemMouseLeave.subscribe(() => {
      this.removeClassFromCheckbox('hover');
    });
  }

  private subscribeToItemMouseDown() {
    this.itemMouseDown.subscribe(() => {
      this.addClassToCheckbox('active');
    });
  }

  private subscribeToItemMouseUp() {
    this.itemMouseUp.subscribe(() => {
      this.removeClassFromCheckbox('active');
    });
  }

  private addClassToCheckbox(className: string) {
    this.checkboxElement()?.classList.add(className);
  }

  private removeClassFromCheckbox(className: string) {
    this.checkboxElement()?.classList.remove(className);
  }

  private checkboxElement() {
    return this.host.shadowRoot.querySelector('groupui-checkbox');
  }

  private isTriggerElementOfSubmenu(): boolean {
    return this.host.getAttribute('slot') === 'trigger';
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  render() {
    return (
      <Host role="menuitem" aria-haspopup={this.isTriggerElementOfSubmenu() ? 'true' : null}>
        <button type="button" disabled={this.disabled}>
          <slot name="start"></slot>
          {this.checkbox && <groupui-checkbox checked={this.active} tabIndex={-1}></groupui-checkbox>}
          <div id="text">
            <slot></slot>
            <slot name="description"></slot>
          </div>
          <slot name="end"></slot>
          {this.active && !this.checkbox && <groupui-icon name="check-24"></groupui-icon>}
          {this.isTriggerElementOfSubmenu() && <groupui-icon name="chevron-right-24" aria-hidden="true"></groupui-icon>}
        </button>
      </Host>
    );
  }
}
